<?php
require __DIR__.'/concurrency-runtime.php';
$directory=concurrencyDirectory((string)($argv[1]??''));$config=concurrencyConfig($directory);$db=Db::getInstance()->getLink();$ids=implode(',',array_map('intval',array_column($config['sales'],'cartId')));$orders=$db->query('SELECT id_order,id_cart,reference FROM `'._DB_PREFIX_.'orders` WHERE id_cart IN ('.$ids.') ORDER BY id_order')->fetchAll(PDO::FETCH_ASSOC);$facts=[];
foreach($orders as $row){$order=new Order((int)$row['id_order']);$payments=[];foreach($order->getOrderPaymentCollection() as $payment)$payments[]=['id'=>(int)$payment->id,'amount_cents'=>(int)round(100*(float)$payment->amount),'method'=>$payment->payment_method,'transaction'=>$payment->transaction_id];$invoices=[];foreach($order->getInvoicesCollection() as $invoice)$invoices[]=(int)$invoice->id;$stockId=(int)StockAvailable::getStockAvailableIdByProductId($config['productId'],0,1);$s=$db->prepare('SELECT physical_quantity,sign FROM `'._DB_PREFIX_.'stock_mvt` WHERE id_order=? AND id_stock=?');$s->execute([(int)$order->id,$stockId]);$movements=$s->fetchAll(PDO::FETCH_ASSOC);$facts[]=['id'=>(int)$order->id,'cartId'=>(int)$order->id_cart,'payments'=>$payments,'invoiceIds'=>$invoices,'movements'=>array_map(static fn($m)=>['quantity'=>(int)$m['physical_quantity'],'sign'=>(int)$m['sign']],$movements)];}
Cache::clean('*');$statuses=[];$effects=[];foreach($config['sales'] as $sale){$id=$sale['command']['operation_id'];$s=$db->prepare('SELECT status FROM `'.$config['tables']['journal'].'` WHERE request_id=?');$s->execute([$id]);$statuses[]=$s->fetchColumn();$s=$db->prepare('SELECT COUNT(*) FROM `'.$config['tables']['effects'].'` WHERE operation_id=?');$s->execute([$id]);$effects[]=(int)$s->fetchColumn();}
echo json_encode(['mode'=>'local-native-concurrency','productId'=>$config['productId'],'stock'=>(int)StockAvailable::getQuantityAvailableByProduct($config['productId'],0,1),'orders'=>$facts,'saleStatuses'=>$statuses,'saleEffects'=>$effects,'remoteShopTouched'=>false],JSON_THROW_ON_ERROR)."\n";
if(($argv[2]??'')==='cleanup')foreach(['effects','carts','journal'] as $table)$db->exec('DROP TABLE `'.$config['tables'][$table].'`');
